<template><view class="page"><view class="card"><view class="title">AI 客服</view><textarea v-model="message" maxlength="500" placeholder="例如：什么时候发货？尺码怎么选？"/><button @click="ask">发送</button><view v-if="answer" class="answer">{{answer}}</view></view></view></template>
<script>import{sudiAiCustomer}from"@/api/sudi_ai.js";export default{data(){return{message:"",answer:""}},methods:{async ask(){if(!this.message.trim())return;try{const r=await sudiAiCustomer({message:this.message.trim()});const d=r&&r.data?r.data:{};this.answer=d.handoff_to_crmeb?"这个问题涉及订单/售后操作，将交给商城正式流程处理。":"已识别你的问题类型："+(d.intent||"general")}catch(e){this.answer="AI客服暂时不可用，请使用商城普通客服。"}}}}</script>
<style scoped>.page{padding:28rpx;background:#f8f6f2;min-height:100vh}.card{background:#fff;border-radius:4rpx;padding:28rpx}.title{font-size:36rpx;font-weight:700;margin-bottom:24rpx}textarea{width:100%;height:180rpx;background:#f8f6f2;border-radius:4rpx;padding:20rpx;box-sizing:border-box}button{margin-top:18rpx;background:#1c1d1a;color:#fff;border-radius:2rpx}.answer{margin-top:24rpx;line-height:1.6;color:#555}</style>